add('Thread-scaling benchmark requires an advertised Threads option matching the requested count','El benchmark requiere una opción Threads anunciada que coincida con el número solicitado|Le benchmark exige une option Threads annoncée correspondant au nombre demandé|Thread-Skalierung erfordert eine gemeldete Threads-Option mit der angeforderten Anzahl|O benchmark exige uma opção Threads anunciada correspondente à contagem solicitada|Il benchmark richiede un’opzione Threads dichiarata corrispondente al numero richiesto|Benchmark vereist een aangeboden Threads-optie die overeenkomt met het gevraagde aantal|Benchmark wymaga zgłoszonej opcji Threads zgodnej z żądaną liczbą')
add('Official results were selected for manual replacement.','Se seleccionaron resultados oficiales para reemplazo manual.|Des résultats officiels ont été sélectionnés pour remplacement manuel.|Offizielle Ergebnisse wurden zum manuellen Ersetzen ausgewählt.|Resultados oficiais foram selecionados para substituição manual.|Sono stati selezionati risultati ufficiali da sostituire manualmente.|Officiële resultaten zijn geselecteerd voor handmatige vervanging.|Wybrano oficjalne wyniki do ręcznej wymiany.')
sources=json.loads((folder/'sources.json').read_text(encoding='utf-8'))
for key in ['ATTACH DATABASE ? AS imported_book','DETACH DATABASE imported_book',r'^\[(\w+) ',' data-report-performance',"json_remove(body,'$.log','$.profile_snapshot') body"]:sources.pop(key,None)
for key in M:sources.setdefault(key,[])
(folder/'sources.json').write_text(json.dumps(sources,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
for i,code in enumerate(('es','fr','de','pt','it','nl','pl')):
    p=folder/(code+'.json');data=json.loads(p.read_text(encoding='utf-8'))
    for key,values in M.items():data['messages'][key]=values[i]
    for key,source in [('ENGINE','Engine'),('SAMPLES','Samples'),('MEAN NPS','Mean NPS'),('MIN NPS','Min NPS'),('MAX NPS','Max NPS')]:data['messages'][key]=data['messages'][source]
    p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
